ContentDetails::RolesEnum ContentDetails::toRolesEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("partner")) {
        return RolesEnum::PARTNER;
    }
    
    if (value == utility::conversions::to_string_t("supplier")) {
        return RolesEnum::SUPPLIER;
    }
    
    if (value == utility::conversions::to_string_t("reseller")) {
        return RolesEnum::RESELLER;
    }
    
    if (value == utility::conversions::to_string_t("customer")) {
        return RolesEnum::CUSTOMER;
    }
    
    throw std::invalid_argument("Invalid value for conversion to std::vector<RolesEnum>");
}

const utility::string_t ContentDetails::fromRolesEnum(const RolesEnum value) const
{
    switch(value)
    {
        
        case RolesEnum::PARTNER: return utility::conversions::to_string_t("partner");
        
        case RolesEnum::SUPPLIER: return utility::conversions::to_string_t("supplier");
        
        case RolesEnum::RESELLER: return utility::conversions::to_string_t("reseller");
        
        case RolesEnum::CUSTOMER: return utility::conversions::to_string_t("customer");
        
    }
}

std::vector<utility::string_t> ContentDetails::fromRolesEnum(const std::vector<RolesEnum>& value) const
{
    std::vector<utility::string_t> ret;
    for (auto it = value.begin(); it != value.end(); it++) {
        ret.push_back(fromRolesEnum(*it));
    }
    return ret;
}

std::vector<ContentDetails::RolesEnum> ContentDetails::toRolesEnum(const std::vector<utility::string_t>& value) const
{
    std::vector<RolesEnum> ret;
    for (auto it = value.begin(); it != value.end(); it++) {
        ret.push_back(toRolesEnum(*it));
    }
    return ret;
}
